class School {TreeMap<Integer,TreeSet<String>> grades=new TreeMap<>();Set<String> names=new HashSet<>();boolean add(String s,int n){if(!names.add(s))return false;grades.computeIfAbsent(n,k->new TreeSet<>()).add(s);return true;}List<String> roster(){List<String> r=new ArrayList<>();for(TreeSet<String> g:grades.values())r.addAll(g);return r;}List<String> grade(int n){return new ArrayList<>(grades.getOrDefault(n,new TreeSet<>()));}}